\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}

\title{Lecture Notes: Estimation and Sampling Distributions}
\author{STAT 302 Course Staff}
\date{Spring 2026}

\begin{document}
\maketitle

\section{Setting}
A field crew weighs a random sample of $n$ salmon from each haul
to estimate the mean weight and its spread for the whole catch.
Throughout these notes the haul is treated as the population and
the weighed fish as a simple random sample from it.

\section{The Sample Mean}
The natural estimator of the population mean weight is the
sample mean
\begin{equation}
\bar{x} = \frac{1}{n} \sum_{i=1}^{n} x_i
\end{equation}
which is unbiased for the haul mean under simple random sampling
and whose sampling variance falls off like $1/n$.

\section{The Sample Variance}
% TODO: fix this equation: change \frac{1}{n} to \frac{1}{n-1} (Bessel's correction; dividing by n makes the estimator biased low)
The spread of individual weights around the sample mean is
summarised by the sample variance
\begin{equation}
s^2 = \frac{1}{n} \sum_{i=1}^{n} (x_i - \bar{x})^2
\end{equation}
Dividing by $n - 1$ rather than $n$ inflates the estimate slightly
and removes the downward bias, because one degree of freedom is
spent estimating the mean first.

\section{Population Quantities}
When the entire population of $N$ fish is weighed, as in a census,
the population variance is defined as
\begin{equation}
\sigma^2 = \frac{1}{N} \sum_{i=1}^{N} (x_i - \mu)^2
\end{equation}
Note the denominator: a census divides by $N$ exactly, and no
correction is needed because $\mu$ is known rather than estimated.

\section{Looking Ahead}
% TODO: add a worked example with the haul-7 dataset once the weights are released
Next week we derive the sampling distribution of $s^2$ under
normality and connect it to the chi-squared family.
\end{document}

